 public class Request {public Dictionary<string,object> Snapshot;public Dictionary<string,Dictionary<string,object>> All;public List<Dictionary<string,object>> Changes=new List<Dictionary<string,object>>();public HashSet<string> Sent=new HashSet<string>();}
