 static void Put(Dictionary<string,object> d,Dictionary<string,object> r){int i=Array.IndexOf(Kinds,J.S(r,"kind"));if(i<0)throw new Exception("Неизвестный тип ответа сервера");string id=J.S(r,"key");var list=J.Rows(d,Lists[i]);var payload=J.Copy(Obj(r,"data"));payload["_syncId"]=id;int index=list.FindIndex(o=>J.S(o,"_syncId")==id);if(i==0)payload["id"]=index<0?(list.Count==0?1:list.Max(x=>J.N(x,"id"))+1):J.N(list[index],"id");if(index<0)list.Add(payload);else list[index]=payload;d[Lists[i]]=list;}
 public static Dictionary<string,object> Merge(Dictionary<string,object> fresh,Request q,Dictionary<string,object> reply,string owner){if(J.S(reply,"owner")!=owner)throw new Exception("Ответ относится к другому аккаунту");var n=J.Copy(fresh);var meta=Obj(n,"_sync");var b=Obj(meta,"base");var oldBase=Obj(Obj(q.Snapshot,"_sync"),"base");var current=Records(n);var conflicts=new List<Dictionary<string,object>>();bool ok=J.B(reply,"ok");foreach(var r in J.Rows(reply,"records")){string key=Key(r);Dictionary<string,object> local,requested;current.TryGetValue(key,out local);q.All.TryGetValue(key,out requested);var old=Obj(oldBase,key);object data=r["data"],oldData=old==null?null:old["data"];
  if(ok&&q.Sent.Contains(key)){if(local==null||requested!=null&&Equal(local["data"],requested["data"]))Put(n,r);b[key]=r;}
