  else if(Equal(local["data"],data)||Equal(data,oldData)){b[key]=r;}
  else{var conflict=J.Copy(r);conflict["local"]=local["data"];conflicts.Add(conflict);}}
  meta["conflicts"]=conflicts;meta["lastSync"]=DateTime.Now.ToString("o");J.Validate(n);foreach(string k in new[]{"products","materials"}){var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var row in J.Rows(n,k))if(!names.Add(J.S(row,"name")))throw new Exception("Совпали названия карточек. Обмен остановлен");}return n;}
